LinearStudy.finiteFlat_standard_closed_s.formalType:
LinearStudy.finiteFlat_standard_closed_socle {r n : ℕ}
  (H : Fin (n + 1) → MvPowerSeries (Fin (n + 1)) (MvPowerSeries (Fin (r + 1)) ℂ))
  (hH : RingTheory.Sequence.IsRegular (MvPowerSeries (Fin (n + 1)) (MvPowerSeries (Fin (r + 1)) ℂ)) (List.ofFn H))
  [Module.Finite (MvPowerSeries (Fin (r + 1)) ℂ)
      (MvPowerSeries (Fin (n + 1)) (MvPowerSeries (Fin (r + 1)) ℂ) ⧸ Ideal.span (Set.range H))]
  [Module.Flat (MvPowerSeries (Fin (r + 1)) ℂ)
      (MvPowerSeries (Fin (n + 1)) (MvPowerSeries (Fin (r + 1)) ℂ) ⧸ Ideal.span (Set.range H))] :
  let A := MvPowerSeries (Fin (n + 1)) (MvPowerSeries (Fin (r + 1)) ℂ) ⧸ Ideal.span (Set.range H);
  have J := Ideal.span (Set.range fun i => (algebraMap (MvPowerSeries (Fin (r + 1)) ℂ) A) (MvPowerSeries.X i));
  ∀ (delta : A ⧸ J) [inst : IsLocalRing (A ⧸ J)],
    delta ∈ Submodule.annihilator (IsLocalRing.maximalIdeal (A ⧸ J)) →
      delta ≠ 0 → Submodule.annihilator (IsLocalRing.maximalIdeal (A ⧸ J)) = Ideal.span {delta}

LinearStudy.powerSeriesQuotient_diagonal.formalType:
LinearStudy.powerSeriesQuotient_diagonal_jacobian.{u_1} {K : Type u_1} [Field K] {n : ℕ}
  (H : Fin (n + 1) → MvPowerSeries (Fin (n + 1)) K) (hzero : ∀ (i : Fin (n + 1)), MvPowerSeries.constantCoeff (H i) = 0)
  [IsArtinianRing (MvPowerSeries (Fin (n + 1)) K ⧸ Ideal.span (Set.range H))] :
  let Q := MvPowerSeries (Fin (n + 1)) K ⧸ Ideal.span (Set.range H);
  have q := Ideal.Quotient.mk (Ideal.span (Set.range H));
  ∃ M,
    LinearStudy.Annihilates (KaehlerDifferential.ideal K Q) M.det ∧
      (Algebra.TensorProduct.lmul' K) M.det = Matrix.det fun i j => q ((MvPowerSeries.pderiv j) (H i))

