  (hq' : RingHom.ker q'.toRingHom = nilradical A) (he : ∀ (a : A), q' a = e (q a)) {delta : A}
  (hd : LinearStudy.Annihilates (nilradical A) delta) (b : B) : b • delta = e b • delta

